async function seedBookings() {
  const rows = BOOKINGS.map(b => ({
    id: b.id, master: b.master,
    start: new Date(b.start).toISOString(),
    end: b.end ? new Date(b.end).toISOString() : new Date(b.start).toISOString(),
    client_id: b.client_id, client_name: b.client_name, client_phone: b.client_phone || '',
    services: b.services || [], status: b.status || 'SERVED',
    online: !!b.online, new_client: !!b.new_client,
    synced_at: new Date().toISOString(),
  }));
  const BATCH = 200;
  for (let i = 0; i < rows.length; i += BATCH) {
    const chunk = rows.slice(i, i + BATCH);
    await supabase('/rest/v1/bookings?on_conflict=id', {
      method: 'POST',
      headers: { Prefer: 'resolution=merge-duplicates' },
      body: JSON.stringify(chunk),
    });
  }
  console.log(`Seeded ${rows.length} historical bookings.`);
}

async function seedKv() {
  // Merge with whatever is already there rather than blindly overwrite —
  // if this runs after the panel has been live for a while, live-entered
  // data (masters added since launch, this month's procurement, etc.)
  // must survive a re-run of this one-time script.
  const getRes = await supabase('/rest/v1/app_kv?select=key,value', { method: 'GET' });
  const existing = {};
  for (const row of await getRes.json()) existing[row.key] = row.value;

  const merged = {
    masters: mergeMasters(existing.masters || [], KV.masters),
    consumable_prices: mergeByItem(existing.consumable_prices || [], KV.consumable_prices),
    day_close: mergeDayClose(existing.day_close || {}, KV.day_close),
    inventory_edits: KV.inventory_edits.concat(existing.inventory_edits || []),
    pnl_fixed: { ...KV.pnl_fixed, ...(existing.pnl_fixed || {}) },
    // frozen never changes after the first seed — it's a fixed historical
    // reference, not something the running app writes to. Keep whatever is
    // already there if this script has run before; otherwise write it once.
    frozen: (existing.frozen && Array.isArray(existing.frozen.dates) && existing.frozen.dates.length)
      ? existing.frozen
      : KV.frozen,
  };

  const rows = Object.entries(merged).map(([key, value]) => ({ key, value }));
  await supabase('/rest/v1/app_kv?on_conflict=key', {
    method: 'POST',
    headers: { Prefer: 'resolution=merge-duplicates' },
    body: JSON.stringify(rows),
  });
  console.log('Seeded masters, consumable_prices, day_close, inventory_edits, pnl_fixed, frozen.');
}

function mergeMasters(existing, seed) {
  const byName = new Map(seed.map(m => [m.name, m]));
  for (const m of existing) byName.set(m.name, m); // live edits win
  return Array.from(byName.values());
}
function mergeByItem(existing, seed) {
  const byItem = new Map(seed.map(c => [c.item, c]));
  for (const c of existing) byItem.set(c.item, c);
  return Array.from(byItem.values());
}
function mergeDayClose(existing, seed) {
  const out = {};
  for (const field of ['prices', 'consumables', 'procurement', 'productSales', 'serviceStatus', 'writeoffs', 'adjustments', 'closed', 'visitZone']) {
    out[field] = { ...(seed[field] || {}), ...(existing[field] || {}) }; // live entries win per date/id
  }
  return out;
}

async function main() {
  await seedBookings();
  await seedKv();
  console.log('History seed complete.');
}
main().catch(err => { console.error(err.message || err); process.exit(1); });
